-- D&D 3.5e SRD Spell Definitions
-- Open Game Content under OGL v1.0a
-- Source: System Reference Document 3.5

dnd35 = dnd35 or {}
dnd35.SPELLS = {}

local function spell(def)
    dnd35.SPELLS[def.id] = def
end

