-- ============================================================
-- HELPER FUNCTIONS
-- ============================================================

function dnd35.list_spells()
    local out = {}
    for id, s in pairs(dnd35.SPELLS) do
        table.insert(out, s)
    end
    table.sort(out, function(a, b) return a.id < b.id end)
    return out
end

function dnd35.spells_by_class(class_id, level)
    local out = {}
    for id, s in pairs(dnd35.SPELLS) do
        local lv = s.level[class_id]
        if lv ~= nil then
            if level == nil or lv == level then
                table.insert(out, s)
            end
        end
    end
    table.sort(out, function(a, b) return a.id < b.id end)
    return out
end

function dnd35.spells_by_school(school)
    local out = {}
    for id, s in pairs(dnd35.SPELLS) do
        if s.school == school then
            table.insert(out, s)
        end
    end
    table.sort(out, function(a, b) return a.id < b.id end)
    return out
end
